HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import kb_lib as K                                          # noqa: E402

TIER_ORDER = ["T0", "T1", "T2", "T3", "T4"]


def _tier_spec(cfg, tier):
    """取某档的定义（缺则用 default_tier 的定义，再缺用全局兜底）。"""
    tiers = cfg.get("tiers") or {}
    spec = tiers.get(tier)
    if not spec:
        spec = tiers.get(cfg.get("default_tier") or "T3") or {}
    if not spec:
        spec = {"label": tier,
                "relevance_min": (cfg.get("defaults") or {}).get("abstract_min_relevance", 0.6),
                "ingest_depth": "standard", "uncapped": False}
    return spec


# ---------------------------------------------------------------- 数据装配

def load_candidates(path):
    with open(path, encoding="utf-8") as f:
        data = json.load(f)
    return data.get("papers") or [], data


def load_cards(days=7, only=None):
    """读 wiki/sources 下近 N 天（按 mtime）的卡片 frontmatter。"""
    src = os.path.join(K.VAULT, "wiki", "sources")
    out = []
    if not os.path.isdir(src):
        return out
    cutoff = datetime.datetime.now() - datetime.timedelta(days=days)
    names = only or sorted(os.listdir(src))
    for fn in names:
        if not fn.endswith(".md"):
            continue
        p = os.path.join(src, fn)
        if not only and datetime.datetime.fromtimestamp(os.path.getmtime(p)) < cutoff:
            continue
        text = K.read_text(p)
        fm_raw, body = K.split_frontmatter(text)
        fm = K.parse_frontmatter(fm_raw)
        fm["_file"] = fn
        fm["_pending"] = "## 待精读" in body and "- [ ]" in body
        fm["_has_conclusion"] = ("## 作者主张" in body) and ("## 批判性评估" in body)
        out.append(fm)
    return out


def term_cooccurrence(papers, min_docs=2, max_share=0.6, top=12):
    """共现主题：出现在 ≥2 篇、又不到 60% 篇数的词 —— 太常见的词没有区分度。"""
    n = len(papers)
    if n < 2:
        return []
    counts, where = {}, {}
    for p in papers:
        text = f"{p.get('title','')} {p.get('abstract','')}"
        for t in set(K.tokenize(text)):
            if len(t) < 2:
                continue
            counts[t] = counts.get(t, 0) + 1
            where.setdefault(t, []).append(p.get("title", "")[:60])
    hits = [(t, c) for t, c in counts.items() if c >= min_docs and c <= max(2, int(n * max_share))]
    hits.sort(key=lambda kv: (-kv[1], kv[0]))
    return [(t, c, where[t][:3]) for t, c in hits[:top]]


def dist(papers, key, order=None):
    d = {}
    for p in papers:
        v = p.get(key) or "—"
        d[v] = d.get(v, 0) + 1
    items = sorted(d.items(), key=lambda kv: (-kv[1], str(kv[0])))
    if order:
        items.sort(key=lambda kv: (order.index(kv[0]) if kv[0] in order else len(order), -kv[1]))
    return items


# ---------------------------------------------------------------- 报告正文

def build_md(papers, meta, cards, conclusion, title):
    today = datetime.date.today().isoformat()
    q = (meta or {}).get("query") or title or "（未命名方向）"
    days = (meta or {}).get("days")
    L = []
    L.append("---")
    L.append(f"created: {today}")
    L.append(f"updated: {today}")
    L.append("type: output")
    L.append("tags: [lit-watch, 归纳报告]")
    L.append(f'aliases: ["{q} 归纳 {today}"]')
    L.append(f'summary: "{today} · {q} · {len(papers)} 篇候选的监控与归纳报告"')
    L.append("sources:")
    for p in papers[:20]:
        doi = p.get("doi")
        if doi:
            L.append(f'  - "https://doi.org/{doi}"')
    L.append("---")
    L.append("")
    L.append(f"# 文献监控与归纳报告 · {q}")
    L.append("")
    L.append(f"- 生成：{today}")
    L.append(f"- 知识库根：`{K.VAULT}`")
    L.append(f"- 检索窗口：{'近 ' + str(days) + ' 天' if days else '（来自候选 JSON，未标注）'}")
    L.append(f"- 候选篇数：**{len(papers)}**"
             + (f"；库内新建卡片：**{len(cards)}**" if cards else ""))
    if (meta or {}).get("generated"):
        L.append(f"- 候选生成日：{(meta or {}).get('generated')}")
    L.append("")

    # —— 归纳（人/AI 写，脚本不代写）——
    L.append("## 归纳与判断")
    L.append("")
    if conclusion:
        L.append(conclusion.strip())
    else:
        L.append("> ⚠️ 待填写：这一节必须由**逐篇读原文**后写出（趋势、共识、分歧、"
                 "对本方向的意义）。脚本只做统计，不给结论。")
    L.append("")

    # —— 分布 ——
    L.append("## 一、分布概览")
    L.append("")
    L.append("| 期刊 | 篇数 |")
    L.append("|---|---|")
    for j, c in dist(papers, "journal")[:15]:
        L.append(f"| {j} | {c} |")
    L.append("")
    tier_d = dist(papers, "journal_tier", order=TIER_ORDER)
    L.append("| tier | 篇数 | 说明 |")
    L.append("|---|---|---|")
    tier_label = {t: _tier_spec(K.load_lit_config(), t).get("label", "") for t in TIER_ORDER}
    for t, c in tier_d:
        L.append(f"| {t} | {c} | {tier_label.get(t, '')} |")
    L.append("")
    n_oa = sum(1 for p in papers if p.get("is_oa"))
    L.append(f"- 开放获取（OpenAlex 判定）：{n_oa}/{len(papers)}")
    if papers:
        yr = {}
        for p in papers:
            y = (p.get("publication_date") or "")[:4] or "—"
            yr[y] = yr.get(y, 0) + 1
        L.append("- 年份分布：" + "；".join(f"{k}×{v}" for k, v in sorted(yr.items())))
    L.append("")

    # —— 候选清单 ——
    L.append("## 二、候选清单")
    L.append("")
    L.append("| # | 标题 | 期刊 | tier | 日期 | DOI | OA |")
    L.append("|---|---|---|---|---|---|---|")
    for i, p in enumerate(papers, 1):
        doi = p.get("doi") or ""
        link = f"[{doi}](https://doi.org/{doi})" if doi else "—"
        oa = "✅" if p.get("is_oa") else "—"
        t = (p.get("title") or "").replace("|", "\\|")[:110]
        L.append(f"| {i} | {t} | {p.get('journal','')} | {p.get('journal_tier','')} "
                 f"| {p.get('publication_date','')} | {link} | {oa} |")
    L.append("")

    # —— 共同主题 ——
    terms = term_cooccurrence(papers)
    L.append("## 三、共同主题（词共现，仅供聚类参考）")
    L.append("")
    if terms:
        for t, c, examples in terms:
            L.append(f"- **{t}**（{c} 篇）：{'；'.join(examples)}")
    else:
        L.append("（候选不足 2 篇或没有重复主题词）")
    L.append("")

    # —— 库内卡片现状 ——
    if cards:
        L.append("## 四、库内卡片现状")
        L.append("")
        L.append("| 卡片 | 期刊 | tier | 可靠度 | 待精读 |")
        L.append("|---|---|---|---|---|")
        for c in cards:
            L.append(f"| [[sources/{c['_file'][:-3]}]] | {c.get('journal','')} "
                     f"| {c.get('journal_tier','')} | {c.get('source_reliability','')} "
                     f"| {'是' if c.get('_pending') else '否'} |")
        L.append("")

    # —— 诚实边界 ——
    L.append("## 五、诚实边界")
    L.append("")
    L.append("- 本报告的统计来自 OpenAlex **元数据与摘要**，不是全文；"
             "摘要里没有的信息一律没有进入本报告。")
    L.append("- 期刊 tier 是**你配置的**相对分档，不代表本报告对论文质量的判断。")
    L.append("- 「共同主题」是分词后的词共现，只用于提示聚类方向，不能当作结论。")
    if cards:
        pend = [c["_file"] for c in cards if c.get("_pending")]
        L.append(f"- 库内 {len(cards)} 张卡片中，仍有 **{len(pend)} 张** 未完成精读"
                 f"（`## 待精读` 未清空）—— 在精读完成前，其结论不得被引用。")
    L.append("")

    # —— 下一步 ——
    L.append("## 六、下一步")
    L.append("")
    L.append("- [ ] 逐篇精读并把 `## 待精读` 清空（先 T0/T1）")
    L.append("- [ ] 把「归纳与判断」补全（趋势 / 共识 / 分歧 / 对自己的意义）")
    L.append("- [ ] 需要 docx / pdf：用同名 `.docx-spec.json` / `.pdf-spec.json` 交给"
             "支持该规格的文档工具生成")
    L.append("- [ ] 更新 `wiki/index.md` 与 `wiki/log_ops.md`")
    L.append("- [ ] 跑 `kb_dois.py` + `lit_catalogue.py`，把新文献纳入下次去重")
    L.append("")
    return "\n".join(L)


def build_blocks(papers, meta, cards, title):
    """输出供文档工具使用的块结构（docx / pdf 共用）。"""
    today = datetime.date.today().isoformat()
    q = (meta or {}).get("query") or title or "文献监控"
    blocks = [
        {"type": "title", "text": f"文献监控与归纳报告 · {q}"},
        {"type": "paragraph", "text": f"生成日期：{today}    候选篇数：{len(papers)}"
                                      f"    知识库：{K.VAULT}"},
        {"type": "heading", "level": 1, "text": "归纳与判断"},
        {"type": "paragraph", "text": "（待填写：须逐篇读原文后写出趋势、共识、分歧与意义。）"},
        {"type": "heading", "level": 1, "text": "一、分布概览"},
        {"type": "table", "header": True, "rows": [["期刊", "篇数"]] +
         [[j, str(c)] for j, c in dist(papers, "journal")[:15]]},
        {"type": "table", "header": True, "rows": [["tier", "篇数"]] +
         [[t, str(c)] for t, c in dist(papers, "journal_tier", order=TIER_ORDER)]},
        {"type": "heading", "level": 1, "text": "二、候选清单"},
        {"type": "table", "header": True, "rows": [["#", "标题", "期刊", "tier", "日期", "DOI"]] +
         [[str(i), (p.get("title") or "")[:90], p.get("journal", ""), p.get("journal_tier", ""),
           p.get("publication_date", ""), p.get("doi", "")] for i, p in enumerate(papers, 1)]},
        {"type": "heading", "level": 1, "text": "三、共同主题（词共现）"},
        {"type": "list", "ordered": False,
         "items": [f"{t}（{c} 篇）：{'；'.join(ex)}" for t, c, ex in term_cooccurrence(papers)]
         or ["（候选不足或没有重复主题词）"]},
    ]
    if cards:
        blocks += [
            {"type": "heading", "level": 1, "text": "四、库内卡片现状"},
            {"type": "table", "header": True, "rows": [["卡片", "期刊", "tier", "可靠度", "待精读"]] +
             [[c["_file"], c.get("journal", ""), c.get("journal_tier", ""),
               c.get("source_reliability", ""), "是" if c.get("_pending") else "否"]
              for c in cards]},
        ]
    blocks += [
        {"type": "heading", "level": 1, "text": "五、诚实边界"},
        {"type": "list", "ordered": False, "items": [
            "统计来自 OpenAlex 元数据与摘要，不是全文。",
            "期刊 tier 是你配置的相对分档，不代表本报告对论文质量的评价。",
            "共同主题是分词共现，仅供聚类参考，不构成结论。",
        ]},
        {"type": "heading", "level": 1, "text": "六、下一步"},
        {"type": "list", "ordered": False, "items": [
            "逐篇精读并清空 `## 待精读`（先 T0/T1）。",
            "补全「归纳与判断」。",
            "更新 wiki/index.md 与 wiki/log_ops.md。",
            "跑 kb_dois.py + lit_catalogue.py，把新文献纳入下次去重。",
        ]},
    ]
    return blocks


def to_pdf_blocks(blocks):
    """把 docx 块结构转成 office_pdf 支持的子集。

    两边并不通用：PDF 只认 heading / paragraph / bullet-list / table / page-break
    （没有 title，列表叫 bullet-list），且 items 必须是纯字符串。
    """
    out = []
    for b in blocks:
        t = b.get("type")
        if t == "title":
            out.append({"type": "heading", "level": 1, "text": b.get("text", "")})
        elif t == "heading":
            out.append({"type": "heading", "level": int(b.get("level") or 1),
                        "text": b.get("text", "")})
        elif t == "paragraph":
            txt = b.get("text")
            if txt is None:
                txt = "".join(r.get("text", "") for r in (b.get("runs") or []))
            out.append({"type": "paragraph", "text": txt})
        elif t == "list":
            items = []
            for it in b.get("items") or []:
                items.append(it if isinstance(it, str)
                             else "".join(r.get("text", "") for r in (it.get("runs") or []))
                             or str(it.get("text", "")))
            out.append({"type": "bullet-list", "items": items})
        elif t == "table":
            out.append({"type": "table", "header": bool(b.get("header")),
                        "rows": [[("" if c is None else str(c)) for c in row]
                                 for row in (b.get("rows") or [])]})
        elif t == "page_break":
            out.append({"type": "page-break"})
    return out


# ---------------------------------------------------------------- 自检

def selftest():
    print("=== lit_report --selftest ===")
    ok = fail = 0

    def chk(name, cond, extra=""):
        nonlocal ok, fail
        if cond:
            print(f"  [ok  ] {name}")
            ok += 1
        else:
            print(f"  [FAIL] {name} {extra}")
            fail += 1

    papers = [
        {"title": "固态电解质界面稳定性研究", "journal": "Nature Materials",
         "journal_tier": "T1", "publication_date": "2026-09-30", "doi": "10.1038/a",
         "is_oa": True, "abstract": "固态电解质 界面 稳定性 锂 枝晶"},
        {"title": "锂枝晶生长的原位观测", "journal": "ACS Energy Letters",
         "journal_tier": "T3", "publication_date": "2026-10-01", "doi": "10.1021/b",
         "is_oa": False, "abstract": "锂 枝晶 原位 观测 固态电解质"},
        {"title": "无关的另一主题论文", "journal": "Ionics", "journal_tier": "T4",
         "publication_date": "2026-10-02", "doi": "", "is_oa": False,
         "abstract": "催化剂 表面 反应"},
    ]
    meta = {"query": "固态电解质", "days": 15, "generated": "2026-10-08"}
    md = build_md(papers, meta, [], "", "固态电解质")
    chk("报告 md 有 frontmatter 与标题", md.startswith("---") and "# 文献监控" in md)
    chk("报告含候选清单表", "## 二、候选清单" in md and "10.1038/a" in md)
    chk("报告未代写结论（占位存在）", "待填写" in md)
    co = term_cooccurrence(papers)
    chk("共现主题能找出跨篇词", any(t in ("电解质", "固态电解质", "枝晶") for t, _, _ in co),
        str(co[:3]))
    chk("共现主题排除仅出现一次的词", all(c >= 2 for _, c, _ in co))
    blocks = build_blocks(papers, meta, [], "固态电解质")
    types = [b["type"] for b in blocks]
    chk("块结构以 title 开头且含 table",
        types[0] == "title" and "table" in types, str(types[:5]))
    chk("块结构字段合法（仅用受支持的 type）",
        set(types) <= {"title", "heading", "paragraph", "list", "table", "image", "page_break"},
        str(set(types)))
    pdf_blocks = to_pdf_blocks(blocks)
    pdf_types = {b["type"] for b in pdf_blocks}
    chk("PDF 规格只使用 office_pdf 支持的块类型",
        pdf_types <= {"heading", "paragraph", "bullet-list", "table", "page-break"},
        str(pdf_types))
    chk("PDF 规格的标题转成 heading（PDF 无 title 块）",
        pdf_blocks[0]["type"] == "heading" and pdf_blocks[0]["text"])
    chk("PDF 规格的列表项都是纯字符串",
        all(isinstance(i, str) for b in pdf_blocks if b["type"] == "bullet-list"
            for i in b["items"]))

    # 落盘：临时输出目录
    import tempfile
    import shutil
    tmp = K.make_temp_dir(prefix="lit-report-selftest-")
    try:
        out = os.path.join(tmp, "r.md")
        with open(out, "w", encoding="utf-8", newline="\n") as f:
            f.write(md)
        docx_spec = {"properties": {"title": "x"}, "blocks": blocks}
        with open(os.path.join(tmp, "r.docx-spec.json"), "w", encoding="utf-8") as f:
            json.dump(docx_spec, f, ensure_ascii=False, indent=2)
        with open(os.path.join(tmp, "r.pdf-spec.json"), "w", encoding="utf-8") as f:
            json.dump({"title": "x", "blocks": to_pdf_blocks(blocks)}, f, ensure_ascii=False, indent=2)
        chk("docx/pdf 规格文件可被 JSON 读回",
            json.load(open(os.path.join(tmp, "r.docx-spec.json"), encoding="utf-8"))["blocks"][0]["type"]
            == "title")
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    print(f"\n{'SELFTEST PASSED' if fail == 0 else 'SELFTEST FAILED'}: {ok}/{ok + fail}")
    return 0 if fail == 0 else 1


# ---------------------------------------------------------------- CLI

def slugify(s, n=40):
    s = re.sub(r"[\\/:*?\"<>|\s]+", "-", (s or "报告").strip())
    return s[:n].strip("-") or "报告"


def main():
    ap = argparse.ArgumentParser(description="把一轮 lit-watch 结果汇总为归纳报告（含 docx/pdf 规格）")
    ap.add_argument("--candidates", default="", help="阶段A 候选 JSON")
    ap.add_argument("--from-sources", action="store_true", help="改为汇总库内新建卡片")
    ap.add_argument("--days", type=int, default=7, help="--from-sources 时取近 N 天的卡片")
    ap.add_argument("--cards", nargs="*", default=[], help="指定卡片文件名（wiki/sources/ 下）")
    ap.add_argument("--title", default="", help="方向名（缺省用候选 JSON 的 query）")
    ap.add_argument("--out", default="", help="输出 md 路径（默认 wiki/outputs/<日期>-<方向>.md）")
    ap.add_argument("--conclusion", default="", help="把你写好的归纳段落（md 文件）并入报告")
    ap.add_argument("--stdout", action="store_true", help="只打印，不写盘")
    ap.add_argument("--selftest", action="store_true")
    args = ap.parse_args()

    if args.selftest:
        return selftest()

    papers, meta = [], {}
    if args.candidates:
        papers, meta = load_candidates(args.candidates)
    cards = []
    if args.from_sources or args.cards:
        cards = load_cards(days=args.days, only=args.cards or None)
    if not papers and not cards:
        print("[!] 没有任何素材：给 --candidates，或用 --from-sources 汇总库内卡片")
        return 2

    title = args.title or (meta or {}).get("query") or "文献监控"
    conclusion = ""
    if args.conclusion and os.path.exists(args.conclusion):
        conclusion = K.read_text(args.conclusion)

    md = build_md(papers, meta, cards, conclusion, title)
    blocks = build_blocks(papers, meta, cards, title)

    if args.stdout:
        print(md)
        return 0

    out = args.out or os.path.join(K.VAULT, "wiki", "outputs",
                                   f"{datetime.date.today().isoformat()}-{slugify(title)}.md")
    os.makedirs(os.path.dirname(out), exist_ok=True)
    with open(out, "w", encoding="utf-8", newline="\n") as f:
        f.write(md)
    docx_spec = out[:-3] + ".docx-spec.json"
    pdf_spec = out[:-3] + ".pdf-spec.json"
    with open(docx_spec, "w", encoding="utf-8", newline="\n") as f:
        json.dump({"properties": {"title": f"文献监控与归纳报告 · {title}", "author": "matsci-kb"},
                   "defaults": {"font": "Aptos", "east_asia_font": "微软雅黑", "font_size_pt": 11},
                   "blocks": blocks}, f, ensure_ascii=False, indent=2)
    with open(pdf_spec, "w", encoding="utf-8", newline="\n") as f:
        json.dump({"title": f"文献监控与归纳报告 · {title}",
                   "author": "matsci-kb",
                   "subject": (meta or {}).get("query") or title,
                   "page_size": "A4",
                   "footer": "第 {page} 页",
                   "blocks": to_pdf_blocks(blocks)}, f, ensure_ascii=False, indent=2)

    print(f"报告已写入: {out}")
    print(f"  docx 规格: {docx_spec}")
    print(f"  pdf  规格: {pdf_spec}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
